mapper.select:
SELECT dt.id, dt.`name`, dt.daily_type, dt.deadline, dt.end_time, dt.file_ref_key, dt.`status`, dt.target_count, dt.task_category_id, dt.urgency_id, dt.progress, dt.task_day, dt.task_hour, dt.task_minute, dt.parent_id, dt.create_by, dt.create_time FROM daily_task dt INNER JOIN daily_task_user dtu ON dtu.master_id = dt.id
and dtu.superintendent_type = 'USER' AND dtu.task_user_type in ('ASSIGNEE','SUPERINTENDENT')
and dt.daily_type = #{param.dailyType}
and dt.daily_type IN
#{dailyType}
AND dtu.target_id = #{param.userId}
AND dt.`name` LIKE CONCAT('%',#{param.keyword},'%')
AND dt.`status` = #{param.status}
AND dt.`status` != 'DRAFT'
AND dt.task_category_id = #{param.taskCategoryId}
AND dt.urgency_id = #{param.urgencyId}
AND dt.create_time between #{param.period.begin} and #{param.period.end}
AND dt.parent_id IS NULL
AND dt.parent_id IS NOT NULL
AND dt.id IN
#{taskId}
GROUP BY dt.id ORDER BY dt.create_time DESC

SELECT COUNT(DISTINCT dt.id) FROM daily_task dt INNER JOIN daily_task_user dtu ON dtu.master_id = dt.id WHERE dt.daily_type = #{param.dailyType} and dtu.superintendent_type = 'USER'
AND dt.create_time between #{param.period.begin} and #{param.period.end}
AND dt.`status` in
#{state}

SELECT
COUNT(DISTINCT dt.id)
FROM
daily_task t1
INNER JOIN daily_task_target t2 ON t1.id = t2.task_id


        AND t2.target_id = #{targetId}


        AND t1.daily_type = #{dailyType}


        and t1.create_time >= #{period.begin}


        and t1.create_time <= #{period.end}

SELECT DISTINCT dt.id FROM daily_task dt INNER JOIN daily_task_target_ref dttr ON dttr.task_id = dt.id INNER JOIN daily_task_target dtt ON dtt.id = dttr.target_ref_id WHERE dt.require_progress IS NULL AND dtt.snapshot = 1
AND dt.id IN
#{taskId}

SELECT DISTINCT dt.id, dt.`name`, dt.daily_type, dt.deadline, dt.end_time, dt.file_ref_key, dt.`status`, dt.target_count, dt.task_category_id, dt.urgency_id, dt.progress, dt.task_day, dt.task_hour, dt.task_minute, dt.parent_id, dt.is_on_duty, dt.create_by, dt.create_time, dt.tenant FROM daily_task dt INNER JOIN daily_task_user dtu ON dtu.master_id = dt.id WHERE dtu.task_user_type = 'ASSIGNEE' AND dtu.superintendent_type = 'GRID_AREA' AND dtu.target_id = #{gridAreaId} AND dt.daily_type = #{dailyType} AND dt.create_time <= #{now}
AND dt.`status` IN
#{status}

SELECT dtu.target_id AS gridAreaId, COUNT(DISTINCT dt.id) AS abnormalTaskCount FROM daily_task dt INNER JOIN daily_task_user dtu ON dtu.master_id = dt.id INNER JOIN daily_record_exception dre ON dre.task_id = dt.id WHERE dt.daily_type = #{dailyType} AND dtu.task_user_type = 'ASSIGNEE' AND dtu.superintendent_type = 'GRID_AREA' AND dtu.target_id IN
#{gridAreaId}
GROUP BY dtu.target_id
